"""Core data types shared across the RAG pipeline."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Optional


@dataclass
class Document:
    """A raw document plus the metadata that describes it.

    ``metadata`` is a flat or nested JSON-ish mapping, e.g.::

        {
          "category": "api",
          "source": "developer-docs",
          "author": "platform-team",
          "published_at": "2024-03-01",
          "popularity": 92,
          "tags": ["authentication", "oauth2"],
        }

    The same mapping is copied onto every :class:`Chunk` produced from the
    document so that filtering and ranking can use it at retrieval time.
    """

    content: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    doc_id: Optional[str] = None


@dataclass
class Chunk:
    """A retrievable text fragment with inherited document metadata."""

    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    chunk_id: str = ""
    doc_id: str = ""
    index: int = 0

    @property
    def source(self) -> Optional[str]:
        return self.metadata.get("source") or self.metadata.get("doc_id")


@dataclass
class RankedChunk:
    """A chunk together with its final relevance score and a breakdown.

    ``score`` is the blended final score used for ranking, while
    ``semantic_score`` and the ``breakdown`` dict let callers inspect *why* a
    chunk was ranked where it was (transparent, debuggable retrieval).
    """

    chunk: Chunk
    score: float = 0.0
    semantic_score: float = 0.0
    metadata_score: float = 0.0
    breakdown: Dict[str, float] = field(default_factory=dict)

    @property
    def text(self) -> str:
        return self.chunk.text

    @property
    def metadata(self) -> Dict[str, Any]:
        return self.chunk.metadata

    @property
    def doc_id(self) -> str:
        return self.chunk.doc_id

    def __repr__(self) -> str:  # pragma: no cover - debugging aid
        return (
            f"RankedChunk(score={self.score:.4f}, "
            f"doc_id={self.doc_id!r}, chunk={self.chunk.index})"
        )

"""Text utilities: tokenisation shared by the content embedder, the query
parser and the metadata tag matcher."""

from __future__ import annotations

import re
from typing import Iterable, List, Set

# Tokens are letter/digit runs; underscores and dots are kept so identifiers
# such as ``access_token`` or ``v1.auth`` survive tokenisation as atoms.
_TOKEN_RE = re.compile(r"[A-Za-z0-9_]+(?:\.[A-Za-z0-9_]+)*|[A-Za-z0-9_]+")

# Very frequent words add no signal for keyword/tag matching and only dilute
# the metadata-overlap component of the ranker.
STOPWORDS: Set[str] = {
    "a", "an", "the", "and", "or", "but", "if", "then", "else", "for", "to",
    "of", "in", "on", "at", "by", "with", "from", "as", "is", "are", "was",
    "were", "be", "been", "being", "do", "does", "did", "have", "has", "had",
    "how", "what", "which", "who", "whom", "why", "when", "where", "this",
    "that", "these", "those", "it", "its", "we", "you", "they", "them",
    "our", "your", "their", "not", "no", "yes", "can", "could", "would",
    "should", "may", "might", "will", "shall", "than", "also", "etc", "eg",
    "i", "us", "about", "into", "over", "under", "between", "out", "up",
    "down", "more", "most", "such", "only", "own", "same", "so", "too",
}


def tokenize(text: str) -> List[str]:
    """Return the ordered tokens of *text* (lower-cased)."""
    return _TOKEN_RE.findall((text or "").lower())


def term_set(text: str) -> Set[str]:
    """Unique tokens of *text* without stopwords."""
    return {t for t in tokenize(text) if t not in STOPWORDS}


def query_terms(query: str) -> Set[str]:
    """Terms of a user query used for metadata overlap scoring."""
    return term_set(query)


def flatten(values: Iterable[object]) -> List[str]:
    """Flatten metadata values (str / numbers / lists) into strings."""
    out: List[str] = []
    for v in values:
        if isinstance(v, (list, tuple, set)):
            out.extend(flatten(v))
        elif isinstance(v, (str, int, float)):
            out.append(str(v))
    return out

"""Content embedding layer.

The default :class:`TfidfEmbedder` is fully deterministic and runs on the
standard library only (sparse TF-IDF vectors + cosine similarity). It is a
drop-in stand-in for a neural embedder: subclass :class:`Embedder` and
implement ``embed``/``fit`` to use sentence-transformers, OpenAI or any other
model without touching the rest of the pipeline.
"""

from __future__ import annotations

import math
import re
from abc import ABC, abstractmethod
from collections import Counter
from typing import Dict, Iterable, List, Optional, Sequence, Set, Tuple

from .text import STOPWORDS, tokenize

# A document/query vector is a sparse mapping ``term -> weight``. After
# L2-normalisation, cosine similarity is a simple dot product.
Vector = Dict[str, float]


def cosine_similarity(a: Vector, b: Vector) -> float:
    """Cosine similarity of two sparse L2-normalised vectors."""
    if not a or not b:
        return 0.0
    # iterate over the smaller vector
    if len(a) > len(b):
        a, b = b, a
    dot = 0.0
    for term, wa in a.items():
        wb = b.get(term)
        if wb:
            dot += wa * wb
    return dot


class Embedder(ABC):
    """Interface implemented by content embedders used by the pipeline."""

    name: str = "base"

    @abstractmethod
    def fit(self, texts: Sequence[str]) -> None:
        """Learn any corpus-level statistics needed to embed text."""

    @abstractmethod
    def embed(self, text: str) -> Vector:
        """Return an L2-normalised sparse vector for *text*."""

    def embed_many(self, texts: Sequence[str]) -> List[Vector]:
        return [self.embed(t) for t in texts]


class _TermBuilder:
    """Yield contiguous word n-grams from a token list, e.g. unigrams and
    bigrams, so that phrases such as ``rate limiting`` are captured."""

    __slots__ = ("min_n", "max_n")

    def __init__(self, ngram_range: Tuple[int, int] = (1, 2)) -> None:
        self.min_n, self.max_n = ngram_range

    def terms(self, tokens: Sequence[str]) -> Iterable[str]:
        n = len(tokens)
        for start in range(n):
            for size in range(self.min_n, min(self.max_n, n - start) + 1):
                yield " ".join(tokens[start : start + size])


class TfidfEmbedder(Embedder):
    """Sparse TF-IDF embedder with configurable word n-grams.

    Vectors are L2-normalised so that cosine similarity reduces to a dot
    product between the sparse term vectors.
    """

    name = "tfidf"

    def __init__(
        self,
        ngram_range: Tuple[int, int] = (1, 2),
        min_df: int = 1,
        sublinear_tf: bool = True,
        max_features: Optional[int] = None,
    ) -> None:
        self.ngram_range = ngram_range
        self.min_df = min_df
        self.sublinear_tf = sublinear_tf
        self.max_features = max_features
        self._idf: Dict[str, float] = {}
        self._vocab: Set[str] = set()
        self._fitted = False
        self._builder = _TermBuilder(ngram_range)

    # ------------------------------------------------------------------ #
    # Public API
    # ------------------------------------------------------------------ #
    def fit(self, texts: Sequence[str]) -> None:
        document_freq: Counter = Counter()
        doc_count = 0
        for text in texts:
            doc_count += 1
            for term in set(self._terms_of(text)):
                document_freq[term] += 1

        if doc_count == 0:
            self._fitted = True
            return

        # Drop terms that appear in fewer than min_df documents.
        terms = [t for t, df in document_freq.items() if df >= self.min_df]
        if self.max_features is not None and len(terms) > self.max_features:
            terms.sort(key=lambda t: (document_freq[t], t), reverse=True)
            terms = terms[: self.max_features]

        self._idf = {
            term: math.log((1.0 + doc_count) / (1.0 + document_freq[term])) + 1.0
            for term in terms
        }
        self._vocab = set(terms)
        self._fitted = True

    def embed(self, text: str) -> Vector:
        if not self._fitted:
            raise RuntimeError("TfidfEmbedder.fit() must be called before embed().")
        if not text:
            return {}

        counts: Counter = Counter()
        token_total = 0
        for token in tokenize(text):
            if token in STOPWORDS:
                continue
            token_total += 1
        for term in self._terms_of(text):
            counts[term] += 1

        if token_total == 0:
            return {}

        weights: Dict[str, float] = {}
        for term, count in counts.items():
            idf = self._idf.get(term)
            if idf is None:
                continue
            tf = 1.0 + math.log(count) if self.sublinear_tf else float(count)
            weights[term] = tf * idf

        return _l2_normalise(weights)

    def embed_many(self, texts: Sequence[str]) -> List[Vector]:
        return [self.embed(t) for t in texts]

    # ------------------------------------------------------------------ #
    # Helpers
    # ------------------------------------------------------------------ #
    def _terms_of(self, text: str) -> Iterable[str]:
        tokens = [t for t in tokenize(text) if t not in STOPWORDS]
        return self._builder.terms(tokens)


def _l2_normalise(weights: Dict[str, float]) -> Vector:
    norm = math.sqrt(sum(w * w for w in weights.values()))
    if norm == 0.0:
        return {}
    return {term: w / norm for term, w in weights.items()}

"""Metadata filtering.

Filters are declarative and applied *before* vector search so that retrieval
never sees out-of-scope documents. A filter is a mapping from a metadata path
(dotted keys supported, e.g. ``owner.team``) to a condition::

    {"category": "api",                          # equality (contains for lists)
     "published_at": {"$gte": "2024-01-01"},     # comparison / operators
     "tags": {"$in": ["oauth2", "sso"]},
     "source": {"$ne": "legacy"},
     "retired": {"$exists": False}}

Multiple field conditions AND together; a list of filter dicts also ANDs.
"""

from __future__ import annotations

import re
from typing import Any, Dict, Iterable, List, Optional

_MISSING = object()

_OPERATORS = frozenset(
    {"$eq", "$ne", "$in", "$nin", "$gt", "$gte", "$lt", "$lte", "$exists", "$regex"}
)


def _dig(metadata: Dict[str, Any], path: str) -> Any:
    """Resolve a possibly dotted metadata path."""
    node: Any = metadata
    for part in path.split("."):
        if isinstance(node, dict) and part in node:
            node = node[part]
        else:
            return _MISSING
    return node


def _contains(actual: Any, expected: Any) -> bool:
    """Equality that understands lists on either side (set semantics)."""
    if isinstance(actual, (list, tuple, set)):
        if isinstance(expected, (list, tuple, set)):
            return not set(actual).isdisjoint(expected)
        return expected in actual
    if isinstance(expected, (list, tuple, set)):
        return actual in expected
    return actual == expected


def _compare(actual: Any, op: str, expected: Any) -> bool:
    if actual is _MISSING or actual is None:
        return False
    if isinstance(expected, str) and isinstance(actual, str):
        # Lexicographic comparison works for ISO-8601 dates of equal shape.
        pass
    try:
        left, right = float(actual), float(expected)
    except (TypeError, ValueError):
        # Non-numeric comparison (e.g. ISO dates).
        try:
            left, right = str(actual), str(expected)
        except Exception:
            return False
    if op == "$gt":
        return left > right
    if op == "$gte":
        return left >= right
    if op == "$lt":
        return left < right
    if op == "$lte":
        return left <= right
    raise ValueError(f"Unsupported comparison operator: {op}")


def _apply_operator(actual: Any, op: str, expected: Any) -> bool:
    if op == "$eq":
        return _contains(actual, expected)
    if op == "$ne":
        return not _contains(actual, expected)
    if op == "$in":
        if not isinstance(expected, (list, tuple, set)):
            raise TypeError("$in expects a list of candidate values")
        return _contains(actual, list(expected))
    if op == "$nin":
        if not isinstance(expected, (list, tuple, set)):
            raise TypeError("$nin expects a list of candidate values")
        return not _contains(actual, list(expected))
    if op == "$exists":
        exists = actual is not _MISSING and actual is not None
        return exists if expected else not exists
    if op == "$regex":
        if actual is _MISSING:
            return False
        return re.search(expected, str(actual)) is not None
    return _compare(actual, op, expected)


def _field_matches(actual: Any, condition: Any) -> bool:
    # Operator block, e.g. {"$gte": ..., "$lte": ...} -> AND of all ops.
    if isinstance(condition, dict) and condition and set(condition).issubset(_OPERATORS):
        for op, expected in condition.items():
            if not _apply_operator(actual, op, expected):
                return False
        return True
    # Plain scalar / nested-dict equality.
    return _contains(actual, condition)


def matches(metadata: Dict[str, Any], filter_dict: Optional[Dict[str, Any]]) -> bool:
    """True when *metadata* satisfies every condition in *filter_dict*."""
    if not filter_dict:
        return True
    for path, condition in filter_dict.items():
        if not _field_matches(_dig(metadata, path), condition):
            return False
    return True


def apply_filters(
    chunks: Iterable[Any],
    filters: Optional[Dict[str, Any]],
) -> List[Any]:
    """Return only chunks whose ``.metadata`` satisfies *filters*.

    The input items may be either :class:`~metadata_rag.types.Chunk` objects
    (with a ``.metadata`` attribute) or ``(chunk, vector)`` tuples used
    internally by the vector store.
    """
    if not filters:
        return list(chunks)
    keep: List[Any] = []
    for item in chunks:
        metadata = item.metadata if hasattr(item, "metadata") else item[0].metadata
        if matches(metadata, filters):
            keep.append(item)
    return keep

"""Metadata-aware relevance ranking.

After the vector store returns semantic candidates, the ranker re-scores them
by blending **content relevance** with **metadata relevance**:

*content relevance* = TF-IDF cosine similarity of the query against the chunk.

*metadata relevance* is the weighted mean of three normalised signals:

- **tag overlap**  — how many of the query's content words also appear in the
  document's ``title`` / ``category`` / ``tags`` / ... metadata. This rewards
  documents whose *declared subject* matches the user's intent, even when the
  wording of the body differs.
- **freshness**    — recency of ``published_at`` (or another date field)
  relative to the other candidates in the result set.
- **authority**    — ``popularity`` / ``rating`` / ``views`` normalised against
  the other candidates.

All component scores lie in [0, 1] and are explained in each
:class:`~metadata_rag.types.RankedChunk.breakdown`, keeping the ranking
transparent and debuggable.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Dict, List, Optional, Sequence, Tuple

from .text import STOPWORDS, flatten, query_terms, tokenize
from .types import Chunk, RankedChunk

_ISO_DATE_FIELDS = ("published_at", "date", "created_at", "updated_at")


def _to_timestamp(value: Any) -> Optional[float]:
    """Parse ISO-8601 strings or numeric timestamps into seconds since epoch."""
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        text = value.strip()
        try:
            dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
            return dt.timestamp()
        except ValueError:
            pass
        try:
            return float(text)
        except ValueError:
            return None
    return None


def _first_number(metadata: Dict[str, Any], fields: Sequence[str]) -> Optional[float]:
    for name in fields:
        value = metadata.get(name)
        if isinstance(value, (int, float)):
            return float(value)
        if isinstance(value, str):
            try:
                return float(value)
            except ValueError:
                continue
    return None


def _min_max(values: Sequence[float]) -> Tuple[float, float]:
    if not values:
        return 0.0, 0.0
    return min(values), max(values)


def _normalise(values: Sequence[float]) -> Dict[int, float]:
    """Return index -> score in [0,1] (min-max) for the given values."""
    lo, hi = _min_max(values)
    if hi == lo:
        return {i: 1.0 for i in range(len(values))}
    return {i: (v - lo) / (hi - lo) for i, v in enumerate(values)}


@dataclass
class BoostConfig:
    """Knobs controlling how metadata shapes the final relevance score."""

    # Shares of the *final* score coming from content vs. metadata.
    content_weight: float = 0.70
    metadata_weight: float = 0.30

    # Relative weights of the metadata signals (normalised internally).
    tag_weight: float = 0.45
    recency_weight: float = 0.35
    authority_weight: float = 0.20

    recency_field: str = "published_at"
    authority_fields: Tuple[str, ...] = ("popularity", "rating", "views", "upvotes")
    # Metadata fields whose tokens are matched against the query terms.
    metadata_keyword_fields: Tuple[str, ...] = (
        "title",
        "category",
        "tags",
        "summary",
        "author",
        "doc_id",
    )


def _metadata_terms(chunk: Chunk, fields: Sequence[str]) -> set:
    """Tokenised union of selected metadata values (title/tags/category/...)."""
    tokens: set = set()
    for name in fields:
        value = chunk.metadata.get(name)
        if value is None:
            continue
        for piece in flatten([value]):
            tokens.update(tokenize(piece))
    return tokens - STOPWORDS


def rank_candidates(
    query: str,
    candidates: Sequence[Tuple[float, Chunk]],
    config: Optional[BoostConfig] = None,
) -> List[RankedChunk]:
    """Rank ``(semantic_score, chunk)`` candidates by blended relevance.

    Returns a list of :class:`RankedChunk` sorted by descending ``score``.
    """
    cfg = config or BoostConfig()
    n = len(candidates)
    if n == 0:
        return []

    qterms = query_terms(query)
    sims = [sim for sim, _ in candidates]
    chunks = [chunk for _, chunk in candidates]

    # --- signal 1: query <-> metadata keyword overlap ------------------- #
    meta_term_sets = [_metadata_terms(c, cfg.metadata_keyword_fields) for c in chunks]
    tag_scores = [
        (len(qterms & terms) / len(qterms)) if qterms else 0.0
        for terms in meta_term_sets
    ]

    # --- signal 2: recency (only if at least one candidate has a date) -- #
    date_values = [
        _to_timestamp(c.metadata.get(cfg.recency_field)) for c in chunks
    ]
    dated_idx = [i for i, v in enumerate(date_values) if v is not None]
    has_recency = len(dated_idx) > 1 or (len(dated_idx) == 1 and n > 1)
    recency_scores: Dict[int, float] = {}
    if has_recency:
        raw = [date_values[i] for i in dated_idx]
        norm = _normalise(raw)
        for pos, i in enumerate(dated_idx):
            recency_scores[i] = norm[pos]

    # --- signal 3: authority (popularity/rating/...) -------------------- #
    auth_values = [
        _first_number(c.metadata, cfg.authority_fields) for c in chunks
    ]
    auth_idx = [i for i, v in enumerate(auth_values) if v is not None]
    has_authority = len(auth_idx) > 1 or (len(auth_idx) == 1 and n > 1)
    authority_scores: Dict[int, float] = {}
    if has_authority:
        raw = [auth_values[i] for i in auth_idx]
        norm = _normalise(raw)
        for pos, i in enumerate(auth_idx):
            authority_scores[i] = norm[pos]

    # --- blend ---------------------------------------------------------- #
    ranked: List[RankedChunk] = []
    for i, chunk in enumerate(chunks):
        # Metadata score = weighted mean over the applicable signals.
        parts: List[Tuple[float, float]] = []  # (value, weight)
        if qterms:
            parts.append((tag_scores[i], cfg.tag_weight))
        if has_recency:
            parts.append((recency_scores.get(i, 0.0), cfg.recency_weight))
        if has_authority:
            parts.append((authority_scores.get(i, 0.0), cfg.authority_weight))

        if parts:
            total_w = sum(w for _, w in parts)
            meta_score = sum(v * w for v, w in parts) / total_w
        else:
            meta_score = 0.0

        final = cfg.content_weight * sims[i] + cfg.metadata_weight * meta_score

        ranked.append(
            RankedChunk(
                chunk=chunk,
                score=final,
                semantic_score=sims[i],
                metadata_score=meta_score,
                breakdown={
                    "semantic": round(sims[i], 6),
                    "tag_overlap": round(tag_scores[i], 6),
                    "freshness": round(recency_scores.get(i, 0.0), 6),
                    "authority": round(authority_scores.get(i, 0.0), 6),
                    "metadata": round(meta_score, 6),
                    "final": round(final, 6),
                },
            )
        )

    ranked.sort(key=lambda r: r.score, reverse=True)
    return ranked

