"""Document loading from JSON / Markdown / plain-text files.

JSON is the recommended format because it lets documents carry rich metadata
explicitly::

    {
      "id": "api-auth-001",
      "title": "Authentication API reference",
      "content": "... body text ...",
      "category": "api",
      "source": "developer-docs",
      "author": "platform-team",
      "published_at": "2024-05-10",
      "popularity": 95,
      "tags": ["authentication", "oauth2"]
    }

Files may contain a single object, a list of objects, or ``{"documents": [...]}``.
All keys other than the body/id keys become document metadata.
"""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any, Dict, List, Optional

from .types import Document

_BODY_KEYS = {"content", "text", "body"}
_ID_KEYS = {"doc_id", "id"}


def _document_from_mapping(data: Dict[str, Any], fallback_id: str) -> Optional[Document]:
    body = next((data[k] for k in _BODY_KEYS if data.get(k)), None)
    if body is None or not str(body).strip():
        return None

    doc_id = None
    for key in _ID_KEYS:
        if data.get(key):
            doc_id = str(data[key])
            break
    doc_id = doc_id or fallback_id

    metadata = {k: v for k, v in data.items() if k not in _BODY_KEYS | _ID_KEYS}
    metadata["doc_id"] = doc_id
    return Document(content=str(body).strip(), metadata=metadata, doc_id=doc_id)


def _parse_json(path: Path) -> List[Dict[str, Any]]:
    with open(path, "r", encoding="utf-8") as handle:
        data = json.load(handle)
    if isinstance(data, list):
        return [d for d in data if isinstance(d, dict)]
    if isinstance(data, dict):
        nested = data.get("documents")
        if isinstance(nested, list):
            return [d for d in nested if isinstance(d, dict)]
        return [data]
    return []


def _parse_text(path: Path) -> Document:
    text = path.read_text(encoding="utf-8", errors="replace").strip()
    doc_id = path.stem
    title = text.splitlines()[0][:120] if text else ""
    metadata: Dict[str, Any] = {
        "doc_id": doc_id,
        "source": str(path.parent.name) if path.parent.name else path.name,
        "title": title,
        "file_name": path.name,
        "category": "text",
    }
    return Document(content=text, metadata=metadata, doc_id=doc_id)


def load_documents(directory: str, pattern: str = "*") -> List[Document]:
    """Load every supported file under *directory* (recursively)."""
    root = Path(directory)
    if not root.exists():
        return []

    documents: List[Document] = []
    for path in sorted(root.rglob(pattern)):
        if not path.is_file():
            continue
        suffix = path.suffix.lower()
        if suffix in {".json"}:
            for item in _parse_json(path):
                doc = _document_from_mapping(item, path.stem)
                if doc is not None:
                    doc.metadata.setdefault("source", path.stem)
                    documents.append(doc)
        elif suffix in {".md", ".txt", ".rst"}:
            documents.append(_parse_text(path))
    return documents

"""Retrieval evaluation helpers.

Metrics computed over a set of labelled test cases::

    cases = [
        EvaluationCase(
            query="how do users get access tokens?",
            filters={"category": "api"},
            expected_doc_ids=["api-auth-001", "api-rate-limits-010"],
        ),
    ]

Two metrics are reported for each case and aggregated:

- ``hit@k``    — did at least one expected document appear in the top k?
- ``recall@k`` — what fraction of the expected documents appeared in top k?
"""

from __future__ import annotations

from dataclasses import dataclass, field
from statistics import mean
from typing import Dict, List, Optional, Sequence

from .retriever import Retriever


@dataclass
class EvaluationCase:
    query: str
    expected_doc_ids: List[str]
    filters: Optional[Dict[str, object]] = None
    top_k: int = 3


@dataclass
class CaseMetrics:
    query: str
    hit_at_k: float
    recall_at_k: float
    retrieved_doc_ids: List[str]


@dataclass
class EvaluationReport:
    cases: List[CaseMetrics] = field(default_factory=list)

    @property
    def mean_hit_at_k(self) -> float:
        return mean([c.hit_at_k for c in self.cases]) if self.cases else 0.0

    @property
    def mean_recall_at_k(self) -> float:
        return mean([c.recall_at_k for c in self.cases]) if self.cases else 0.0

    def summary(self) -> Dict[str, float]:
        return {
            "mean_hit_at_k": round(self.mean_hit_at_k, 4),
            "mean_recall_at_k": round(self.mean_recall_at_k, 4),
        }


def evaluate_retrieval(
    retriever: Retriever,
    cases: Sequence[EvaluationCase],
) -> EvaluationReport:
    report = EvaluationReport()
    for case in cases:
        result = retriever.retrieve(
            case.query,
            filters=case.filters,
            top_k=case.top_k,
        )
        retrieved = result.doc_ids
        expected = set(case.expected_doc_ids)
        hits = expected.intersection(retrieved)
        report.cases.append(
            CaseMetrics(
                query=case.query,
                hit_at_k=1.0 if hits else 0.0,
                recall_at_k=len(hits) / len(expected) if expected else 0.0,
                retrieved_doc_ids=retrieved,
            )
        )
    return report
